  function minsLabel(m){m=Math.max(0,Number(m)||0);return `${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}m`;}
  function attTime(v){if(!v)return '—';const d=new Date(v);return isNaN(d)?String(v).slice(11,16):d.toLocaleTimeString('en-AE',{hour:'numeric',minute:'2-digit'});}
  function staffAttendanceTs(date,time,isOut){if(!date||!time)return null;let d=date;if(isOut){const [h,m]=time.split(':').map(Number);if((h*60+m)<=120){const x=new Date(date+'T12:00:00');x.setDate(x.getDate()+1);d=x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')}}return d+'T'+time+':00'}
  async function submitMyAttendance(){const date=$('myAttDate').value,type=$('myAttDayType').value,off=type==='Day Off',split=!off&&!!$('myAttSplit')?.checked;if(!date)return toast('Select duty date.',true);let pin=null,pout=null,s2in=null,s2out=null;if(!off){if(split){const a=$('myAttS1In').value,b=$('myAttS1Out').value,c=$('myAttS2In').value,d=$('myAttS2Out').value;if(!a||!b||!c||!d)return toast('Complete both Split Shift time periods.',true);pin=staffAttendanceTs(date,a,false);pout=staffAttendanceTs(date,b,true);s2in=staffAttendanceTs(date,c,false);s2out=staffAttendanceTs(date,d,true);}else{const a=$('myAttIn').value,b=$('myAttOut').value;if(!a||!b)return toast('Duty Joined and Duty Finished are required.',true);pin=staffAttendanceTs(date,a,false);pout=staffAttendanceTs(date,b,true);}}try{await rpc('staff_attendance_submit_v10',{p_token:state.token,p_operational_date:date,p_punch_in:pin,p_punch_out:pout,p_break_taken:$('myAttBreak').value==='true',p_day_off:off,p_note:$('myAttNote').value.trim()||null,p_split_shift:split,p_shift2_in:s2in,p_shift2_out:s2out});toast('Attendance submitted and saved in your history.');$('myAttNote').value='';$('myAttMonth').value=date.slice(0,7);await loadMyAttendance();}catch(e){toast(e.message,true)}}
  async function loadMyAttendance(){if(!$('myAttMonth')||!state.token)return;const month=$('myAttMonth').value||isoMonth();try{const d=await rpc('staff_attendance_month_v10',{p_token:state.token,p_month:month+'-01'});state.myAttendance=d;const finals=d.records||[],subs=d.submissions||[];const finalMap=new Map(finals.map(x=>[x.operational_date,x]));const latestSub=new Map();for(const s of subs){if(!latestSub.has(s.operational_date))latestSub.set(s.operational_date,s)}const dates=[...new Set([...finals.map(x=>x.operational_date),...subs.map(x=>x.operational_date)])].sort();const rows=dates.map(date=>{const f=finalMap.get(date),s=latestSub.get(date);return {date,display:s||f,final:f,submission:s,recordType:s?(s.status==='Finalized'?'Finalized':'Submitted'):'Final'}});const calc=rows.map(x=>x.final).filter(Boolean),dayOff=rows.filter(x=>(x.display?.day_off)).length,presence=calc.reduce((a,x)=>a+(x.presence_minutes||0),0),net=calc.reduce((a,x)=>a+(x.net_work_minutes||0),0),ot=calc.reduce((a,x)=>a+(x.additional_minutes||0),0),late=calc.filter(x=>x.late_minutes>0).length;$('myAttSummary').textContent=`Records: ${rows.length} · Day Off: ${dayOff} · Final Net: ${minsLabel(net)} · Final OT: ${minsLabel(ot)} · Late days: ${late}`;const work=r=>{if(!r)return '—';if(r.day_off)return 'Day Off';const a=`${attTime(r.punch_in)} – ${attTime(r.punch_out)}`;return r.split_shift?`${a} / ${attTime(r.shift2_in)} – ${attTime(r.shift2_out)}`:a};const status=r=>!r?'—':r.day_off?'Day Off':(!r.punch_in?'Missing In':(!r.punch_out?'Missing Out':(r.split_shift&&(!r.shift2_in||!r.shift2_out)?'Missing Split Punch':'Duty')));$('myAttRows').innerHTML=rows.length?rows.map(x=>{const r=x.display,f=x.final;return `<tr><td>${esc(x.date)}</td><td>${esc(work(r))}</td><td>${f?esc(minsLabel(f.net_work_minutes)):'—'}</td><td>${f?.additional_minutes?`+${esc(minsLabel(f.additional_minutes))}`:'—'}</td><td>${f?.late_minutes?esc(f.late_minutes+' min'):'—'}</td><td>${r?.day_off?'—':(r?.break_taken?'Yes':'No')}</td><td>${esc(status(r))}</td><td>${esc(x.recordType)}</td></tr>`}).join(''):'<tr><td colspan="8" class="empty">No attendance records for this month.</td></tr>';$('myAttCards').innerHTML=rows.length?rows.map(x=>{const r=x.display,f=x.final;return `<div class="my-att-card"><div class="row"><strong>${esc(x.date)}</strong><span>${esc(x.recordType)}</span></div><div class="row"><span>Working Time</span><b>${esc(work(r))}</b></div><div class="row"><span>Final Net</span><b>${f?esc(minsLabel(f.net_work_minutes)):'—'}</b></div><div class="row"><span>Final Overtime</span><b class="ot">${f?.additional_minutes?`+${esc(minsLabel(f.additional_minutes))}`:'—'}</b></div></div>`}).join(''):'<div class="notice">No attendance records for this month.</div>';}catch(e){toast(e.message,true)}}
  function myAttendanceShareMode(){const mode=$('myAttShareMode')?.value||'month',p=$('myAttSharePicker');if(!p)return;p.type=mode==='day'?'date':'month';p.value=mode==='day'?new Date().toISOString().slice(0,10):($('myAttMonth')?.value||isoMonth())}
  function staffShareRows(){const d=state.myAttendance||{},mode=$('myAttShareMode')?.value||'month',pick=$('myAttSharePicker')?.value||($('myAttMonth')?.value||isoMonth()),finals=d.records||[],subs=d.submissions||[];const fm=new Map(finals.map(x=>[x.operational_date,x]));const sm=new Map();for(const s of subs){if(!sm.has(s.operational_date))sm.set(s.operational_date,s)}const dates=[...new Set([...finals.map(x=>x.operational_date),...subs.map(x=>x.operational_date)])].sort().filter(x=>mode==='day'?x===pick:x.startsWith(pick));return dates.map(date=>({date,display:sm.get(date)||fm.get(date),final:fm.get(date)}))}
  async function shareMyAttendanceWhatsApp(){if(!state.myAttendance)await loadMyAttendance();const rows=staffShareRows();if(!rows.length)return toast('No attendance found for selected period.',true);const work=r=>{if(r.day_off)return 'Day Off';const a=`${attTime(r.punch_in)} - ${attTime(r.punch_out)}`;return r.split_shift?`${a} / ${attTime(r.shift2_in)} - ${attTime(r.shift2_out)}`:a};let ot=0;const lines=rows.map(x=>{ot+=x.final?.additional_minutes||0;return `${x.date} | ${work(x.display)} | OT ${x.final?.additional_minutes?minsLabel(x.final.additional_minutes):'—'}`});const label=$('myAttSharePicker')?.value||$('myAttMonth').value;const msg=`GOYA - Staff Attendance
Staff: ${state.user.name}
Period: ${label}

${lines.join('\n')}

Total OT: ${minsLabel(ot)}`;window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank')}
  async function shareMyAttendance(){if(!state.myAttendance)await loadMyAttendance();const rows=staffShareRows();if(!rows.length)return toast('No attendance found for selected period.',true);if(!window.jspdf?.jsPDF)return toast('PDF library is still loading. Please try again.',true);const work=r=>{if(r.day_off)return 'Day Off';const a=`${attTime(r.punch_in)} - ${attTime(r.punch_out)}`;return r.split_shift?`${a} / ${attTime(r.shift2_in)} - ${attTime(r.shift2_out)}`:a};const ot=rows.reduce((a,x)=>a+(x.final?.additional_minutes||0),0),net=rows.reduce((a,x)=>a+(x.final?.net_work_minutes||0),0),label=$('myAttSharePicker')?.value||$('myAttMonth').value;const {jsPDF}=window.jspdf,doc=new jsPDF();doc.setFontSize(17);doc.text('GOYA - Staff Attendance Report',14,18);doc.setFontSize(11);doc.text(`Staff: ${state.user.name}`,14,27);doc.text(`Period: ${label}`,14,34);doc.text(`Final Net Working: ${minsLabel(net)}    Total Overtime: ${minsLabel(ot)}`,14,41);doc.autoTable({startY:48,head:[['Date','Working Time','Overtime']],body:rows.map(x=>[x.date,work(x.display),x.final?.additional_minutes?minsLabel(x.final.additional_minutes):'—']),foot:[['','Total Overtime',minsLabel(ot)]],styles:{fontSize:10,cellPadding:3},headStyles:{fillColor:[38,59,52]},footStyles:{fontStyle:'bold'}});const name=`Goya_Attendance_${state.user.name.replace(/[^a-z0-9]+/gi,'_')}_${label}.pdf`;doc.save(name);toast('PDF downloaded.')}
