  function renderAdminOrders(){$('adminOrdersBody').innerHTML=state.adminOrders.length?state.adminOrders.map(x=>`<tr><td><input class="orderCheck" type="checkbox" value="${x.id}" onchange="GoyaAdmin.updateSelectionCount('orderCheck')"></td><td>${esc(x.order_no)}</td><td>${esc(x.name)}<div class="small muted">${esc(x.sku)}</div></td><td><div class="qty-edit"><input id="orderQtyEdit-${x.id}" type="number" min="0.001" step="0.001" value="${esc(x.quantity)}" aria-label="Quantity for ${esc(x.name)}"><button class="btn secondary tiny" onclick="GoyaAdmin.updateOrderQuantity(${x.id})">Save</button></div></td><td>${esc(x.unit)}</td><td>${esc(x.supplier||'')}</td><td>${pill(x.status)}</td><td>${esc(x.received_date||'')}</td><td>${esc(x.logged_by)}</td><td>${esc(fmtDate(x.created_at))}</td><td>${esc(x.notes||'')}</td></tr>`).join(''):'<tr><td colspan="11" class="empty">No orders.</td></tr>';updateSelectionCount('orderCheck');}
  function selectedChecks(cls){return [...document.querySelectorAll('.'+cls+':checked')].map(x=>x.value);}
  function selectionCounterId(cls){return {orderCheck:'orderSelectedCount',pwCheck:'pwSelectedCount',invCountCheck:'invSelectedCount',complaintCheck:'complaintSelectedCount'}[cls]||null;}
  function updateSelectionCount(cls){const id=selectionCounterId(cls),el=id?$(id):null;if(el)el.textContent=`Selected: ${selectedChecks(cls).length}`;}
  function toggleChecks(cls,val){document.querySelectorAll('.'+cls).forEach(x=>x.checked=val);updateSelectionCount(cls);}
  async function bulkOrderStatus(){const ids=selectedChecks('orderCheck').map(Number);if(!ids.length){toast('Select order rows first.',true);return;}try{await rpc('admin_update_orders',{p_token:state.token,p_ids:ids,p_status:$('bulkStatus').value,p_notes:$('bulkNotes').value.trim()||null});await loadAdminOrders();toast('Order status updated.');}catch(e){toast(e.message,true)}}
