  async function updateOrderQuantity(id){const el=$('orderQtyEdit-'+id),quantity=Number(el?.value);if(!Number.isFinite(quantity)||quantity<=0){toast('Quantity must be greater than zero.',true);return;}try{await rpc('admin_update_order_quantity',{p_token:state.token,p_id:id,p_quantity:quantity});await loadAdminOrders();toast('Order quantity updated.');}catch(e){toast(e.message,true)}}
