  function exportOrdersFoodics(){const masters=state.adminData.master_items||[];const rows=state.adminOrders.map(x=>{const m=masters.find(z=>z.sku===x.sku)||{};return {name:x.name,sku:x.sku,order_quantity:x.quantity,storage_quantity:normalize(x.unit)===normalize(m.storage_unit)?x.quantity:'',total_cost:''}});csv(rows,['name','sku','order_quantity','storage_quantity','total_cost'],'purchase_order.csv');}
  function whatsappSupplier(){const rows=state.adminOrders;if(!rows.length)return toast('No filtered orders.',true);const groups={};rows.forEach(x=>{const k=x.supplier||'Unassigned';(groups[k]??=[]).push(x)});const msg=Object.entries(groups).map(([s,rs])=>`Supplier: ${s}\n`+rs.map(r=>`- ${r.name}: ${r.quantity} ${r.unit}${r.notes&&r.notes.trim()?` (${r.notes.trim()})`:''}`).join('\n')).join('\n\n');window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}

