  function exportPWFoodics(){const grouped=new Map();state.pwRows.forEach(x=>{const key=normalize(x.sku)||normalize(x.name);if(!grouped.has(key))grouped.set(key,{name:x.name,sku:x.sku,storage_quantity:0,ingredients_quantity:0,hasStorage:false,hasIngredients:false});const r=grouped.get(key);const s=Number(x.storage_quantity),i=Number(x.ingredients_quantity);if(x.storage_quantity!==null&&x.storage_quantity!==''&&Number.isFinite(s)){r.storage_quantity+=s;r.hasStorage=true;}if(x.ingredients_quantity!==null&&x.ingredients_quantity!==''&&Number.isFinite(i)){r.ingredients_quantity+=i;r.hasIngredients=true;}});const rows=[...grouped.values()].map(r=>({name:r.name,sku:r.sku,storage_quantity:r.hasStorage?r.storage_quantity:'',ingredients_quantity:r.hasIngredients?r.ingredients_quantity:''}));csv(rows,['name','sku','storage_quantity','ingredients_quantity'],`${$('pwKind').value}.csv`);}

  function renderInventoryAdmin(){$('inventorySessionBody').innerHTML=(state.adminData.inventory_sessions||[]).map(x=>`<tr><td>${esc(x.month)}</td><td>${esc(x.title||'')}</td><td>${x.active?'Active':'Inactive'}</td><td>${esc((x.sections||[]).join(', '))}</td><td>${esc((x.assigned_names||[]).join(', '))}</td><td>${esc(x.notice_text||'')}</td><td><div class="toolbar"><button class="btn secondary tiny" onclick="GoyaAdmin.editInventory('${x.id}')">Edit</button><button class="btn danger tiny" onclick="GoyaAdmin.deleteInventory('${x.id}')">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No sessions.</td></tr>';populateInventoryResetSelectors();}
  function populateInventoryResetSelectors(){const el=$('invResetSession');if(!el)return;const cur=el.value;const sessions=state.adminData.inventory_sessions||[];el.innerHTML='<option value="">Select session</option>'+sessions.map(x=>`<option value="${x.id}">${esc(x.title||'Inventory Count')} — ${esc(String(x.month).slice(0,7))}</option>`).join('');if(sessions.some(x=>x.id===cur))el.value=cur;refreshInventoryResetOptions();}
  function refreshInventoryResetOptions(){const sid=$('invResetSession')?.value,staffEl=$('invResetStaff'),secEl=$('invResetSection');if(!staffEl||!secEl)return;const session=(state.adminData.inventory_sessions||[]).find(x=>x.id===sid);if(!session){staffEl.innerHTML='<option value="">Select staff</option>';secEl.innerHTML='<option value="">Select section</option>';return;}const assigned=session.assigned_staff_ids||[];let staff=(state.adminData.staff||[]).filter(x=>x.active!==false);if(assigned.length)staff=staff.filter(x=>assigned.includes(x.id));staffEl.innerHTML='<option value="">Select staff</option>'+staff.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');secEl.innerHTML='<option value="">Select section</option>'+((session.sections||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join(''));}
  async function resetInventorySubmission(){const sessionId=$('invResetSession')?.value,staffId=$('invResetStaff')?.value,section=$('invResetSection')?.value;if(!sessionId||!staffId||!section){toast('Select inventory session, staff and section.',true);return;}const staff=(state.adminData.staff||[]).find(x=>x.id===staffId),session=(state.adminData.inventory_sessions||[]).find(x=>x.id===sessionId);if(!confirm(`Reset and reopen ${section} inventory count for ${staff?.name||'this staff'} in ${session?.title||'this session'}? Existing count rows and draft for this staff/section will be cleared.`))return;try{await rpc('admin_inventory_reset_count',{p_token:state.token,p_session_id:sessionId,p_staff_id:staffId,p_section:section});await adminLoad();await loadInventoryCounts();toast('Inventory count reopened. Staff can submit again.');}catch(e){toast(e.message,true)}}
  function editInventory(id){const x=(state.adminData.inventory_sessions||[]).find(y=>y.id===id);if(!x)return;$('invId').value=x.id;$('invSessionMonth').value=String(x.month).slice(0,7);$('invTitle').value=x.title||'';$('invNotice').value=x.notice_text||'';$('invActive').checked=x.active;setSectionsChecked('invSection',x.sections||[]);[...$('invAssigned').options].forEach(o=>o.selected=(x.assigned_staff_ids||[]).includes(o.value));}
  function resetInventoryForm(){['invId','invTitle','invNotice'].forEach(id=>$(id).value='');$('invSessionMonth').value=isoMonth();$('invActive').checked=false;setSectionsChecked('invSection',[]);[...$('invAssigned').options].forEach(o=>o.selected=false);}
  async function saveInventorySession(){const month=$('invSessionMonth').value,row={id:$('invId').value||null,month:month?month+'-01':null,title:$('invTitle').value.trim(),notice_text:$('invNotice').value.trim(),active:$('invActive').checked,sections:sectionsChecked('invSection'),assigned_staff_ids:[...$('invAssigned').selectedOptions].map(o=>o.value)};if(!row.month||!row.sections.length){toast('Choose month and at least one section.',true);return;}try{await rpc('admin_inventory_save_session',{p_token:state.token,p_row:row});resetInventoryForm();await adminLoad();toast('Inventory session saved.');}catch(e){toast(e.message,true)}}
  async function deleteInventory(id){if(!confirm('Delete this inventory session?'))return;try{await rpc('admin_delete_inventory_session',{p_token:state.token,p_id:id});await adminLoad();toast('Deleted.');}catch(e){toast(e.message,true)}}
  async function loadInventoryCounts(){try{const m=$('invCountMonth').value||isoMonth();state.inventoryRows=await rpc('admin_inventory_counts',{p_token:state.token,p_month:m+'-01',p_section:$('invCountSection').value||null});$('inventoryCountsBody').innerHTML=state.inventoryRows.length?state.inventoryRows.map(x=>{const item=(state.adminData.master_items||[]).find(i=>i.sku===x.sku)||(state.adminData.internal_items||[]).find(i=>i.sku===x.sku)||{};return `<tr><td><input class="invCountCheck" type="checkbox" value="${x.id}" onchange="GoyaAdmin.updateSelectionCount('invCountCheck')"></td><td>${esc(x.item_name)}</td><td>${esc(x.sku)}</td><td>${esc(x.section)}</td><td>${esc(x.storage_quantity??'')} ${esc(item.storage_unit||'')}</td><td>${esc(x.ingredients_quantity??'')} ${esc(item.ingredient_unit||'')}</td><td>${esc(x.counted_by||'')}</td><td>${esc(fmtDate(x.counted_at))}</td></tr>`}).join(''):'<tr><td colspan="8" class="empty">No inventory counts.</td></tr>';updateSelectionCount('invCountCheck');}catch(e){toast(e.message,true)}}
  function exportInventoryFoodics(){const rows=state.inventoryRows.map(x=>({'Inventory Item Name':x.item_name,'Inventory Item SKU':x.sku,'Storage quantity':x.storage_quantity??'','Ingredients quantity':x.ingredients_quantity??'','Inventory Count ID':''}));csv(rows,['Inventory Item Name','Inventory Item SKU','Storage quantity','Ingredients quantity','Inventory Count ID'],'foodics-inventory-count.csv');}
  async function deleteSelectedInventoryCounts(){const ids=selectedChecks('invCountCheck').map(Number);if(!ids.length)return toast('Select inventory history rows first.',true);if(!confirm('Permanently delete the selected inventory history records?'))return;try{await rpc('admin_delete_history_rows',{p_token:state.token,p_kind:'inventory',p_ids:ids});await loadInventoryCounts();toast('Selected inventory history deleted.');}catch(e){toast(e.message,true)}}

