  function filteredComplaints(){const t=$('complaintAdminType').value,q=normalize($('complaintAdminSearch').value);return state.complaints.filter(x=>(!t||x.type===t)&&(!q||normalize(x.details).includes(q)||normalize(x.staff_name).includes(q)));}
  function renderComplaints(){const rows=filteredComplaints();$('complaintAdminBody').innerHTML=rows.length?rows.map(x=>`<tr><td><input class="complaintCheck" type="checkbox" value="${x.id}" onchange="GoyaAdmin.updateSelectionCount('complaintCheck')"></td><td>${pill(x.type)}</td><td style="min-width:320px;white-space:pre-wrap">${esc(x.details)}</td><td>${esc(x.staff_name)}</td><td>${x.hide_identity?'Yes':'No'}</td><td>${esc(fmtDate(x.created_at))}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No records.</td></tr>';updateSelectionCount('complaintCheck');}
