  async function deleteSelectedComplaints(){const ids=selectedChecks('complaintCheck').map(Number);if(!ids.length)return toast('Select complaint/feedback rows first.',true);if(!confirm('Permanently delete the selected complaint/feedback history?'))return;try{await rpc('admin_delete_history_rows',{p_token:state.token,p_kind:'complaints',p_ids:ids});await loadComplaints();await refreshDashboard();toast('Selected records deleted.');}catch(e){toast(e.message,true)}}

