  async function changeAdminPin(){const current=$('adminPinCurrent').value.trim(),next=$('adminPinNew').value.trim(),confirmPin=$('adminPinConfirm').value.trim();if(!/^\d{4,12}$/.test(next)||next!==confirmPin){toast('New PIN must match and be 4–12 digits.',true);return;}try{await rpc('admin_change_pin',{p_token:state.token,p_current_pin:current,p_new_pin:next});['adminPinCurrent','adminPinNew','adminPinConfirm'].forEach(id=>$(id).value='');toast('Admin PIN changed. Use the new PIN next login.');}catch(e){toast(e.message,true)}}

  function normalizeImportRow(kind,r){const get=(...names)=>{for(const n of names){const k=Object.keys(r).find(x=>normalize(x).replace(/[\s_]/g,'')===normalize(n).replace(/[\s_]/g,''));if(k!==undefined)return r[k]}return ''};return {name:String(get('Name')).trim(),sku:String(get('SKU')).trim(),storage_unit:String(get('Storage Unit')).trim(),ingredient_unit:String(get('Ingredient Unit','Ingredients Unit')).trim(),supplier:kind==='master'?String(get('Supplier')).trim():undefined,items_type:String(get('Items Type','Item Type','Section')).trim()||'Bar'};}
  function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(c===','&&!quoted){row.push(cell);cell='';continue}if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>x!==''))rows.push(row);row=[];continue}cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}const h=rows.shift()||[];return rows.map(r=>Object.fromEntries(h.map((x,i)=>[x,r[i]??''])));}
  function handleUpload(kind,file,mode='upsert'){if(!file)return;const reader=new FileReader();reader.onload=async e=>{try{let rows;if(file.name.toLowerCase().endsWith('.csv'))rows=parseCSV(new TextDecoder().decode(e.target.result));else{const wb=XLSX.read(e.target.result,{type:'array'}),ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{defval:''});}const nrows=rows.map(r=>normalizeImportRow(kind,r)).filter(x=>x.name&&x.sku);if(!nrows.length)throw new Error('No valid rows. Check template headers.');const label=kind==='master'?'Master Items':'Internal Items';if(mode==='replace'){if(!confirm(`REPLACE ALL ${label}? This will delete the current ${label} list and replace it with ${nrows.length} imported item(s). This cannot be undone.`))return;}else if(!confirm(`Import ${nrows.length} item(s) into ${label}? Same SKU = update, new SKU = add. Existing items not in this file will stay.`))return;const fn=mode==='replace'?(kind==='master'?'admin_replace_master_items':'admin_replace_internal_items'):(kind==='master'?'admin_upsert_master_items':'admin_upsert_internal_items');const r=await rpc(fn,{p_token:state.token,p_rows:nrows});await adminLoad();if(mode==='replace')toast(`Replaced list with ${r} row(s).`);else toast(`Import complete: ${r.inserted||0} added, ${r.updated||0} updated.`);}catch(err){toast(err.message,true)}};reader.readAsArrayBuffer(file);}
  function downloadTemplate(kind){const row=kind==='master'?{'Name':'','SKU':'','Storage Unit':'','Ingredient Unit':'','Supplier':'','Items Type':''}:{'Name':'','SKU':'','Storage Unit':'','Ingredient Unit':'','Section':''};csv([row],Object.keys(row),kind==='master'?'Master_Items_Template.csv':'Internal_Items_Template.csv');}
