  async function exportManagementData(){const dataset=$('exportDataset').value,month=$('exportRange').value==='month'?($('exportMonth').value?$('exportMonth').value+'-01':null):null;if($('exportRange').value==='month'&&!month){toast('Select a month.',true);return;}try{const rows=await rpc('admin_export_dataset',{p_token:state.token,p_dataset:dataset,p_month:month});excel(rows,`Goya_${dataset}_${month?month.slice(0,7):'ALL'}.xlsx`,dataset);}catch(e){toast(e.message,true)}}
